#include "career.hpp"
#include <regex>
#include <algorithm>
#include <cmath>
namespace ofo {
CareerRules::CareerRules(const Resources&r){try{auto mapping=parse_data(text_decode(r.read("data/scripts/trackmapping.bed"))).at("Classes");auto source=text_decode(r.read("data/scripts/levels.bed"));std::map<int,std::array<int,7>> prizes;std::regex record(R"rx(\[([0-9]+)\]\s*=\s*\{\s*Name\s*=\s*"[^"]+"[\s\S]*?Winnings\s*=\s*\{([^}]+))rx");for(std::sregex_iterator i(source.begin(),source.end(),record),end;i!=end;++i){std::array<int,7>a{};auto body=(*i)[2].str();std::regex value(R"(\[([1-7])\]\s*=\s*([0-9]+))");for(std::sregex_iterator v(body.begin(),body.end(),value);v!=end;++v)a[std::stoi((*v)[1])-1]=std::stoi((*v)[2]);prizes[std::stoi((*i)[1])]=a;}for(int c=1;c<=4;++c){auto courses=mapping.at(std::to_string(c)).at("Courses");for(auto k=courses.begin();k!=courses.end();++k)for(auto v=k.value().begin();v!=k.value().end();++v){if(!v.value().is_object()||!v.value().contains("Level"))continue;CareerEvent e;e.level=v.value().at("Level");e.car_class=c;e.course=std::stoi(k.key());e.stage=std::stoi(v.key());e.prizes=prizes[e.level];events.push_back(e);}}}catch(const std::exception&){} }
const CareerEvent* CareerRules::event(int id)const{for(auto&e:events)if(e.level==id)return &e;return nullptr;}
void CareerProgress::initialize(){*this=CareerProgress{};initialized=true;}
int CareerProgress::position(int id)const{auto i=positions.find(id);return i==positions.end()?0:i->second;}
bool CareerProgress::unlocked(const CareerRules&r,int id)const{auto e=r.event(id);if(!initialized||!e)return false;if(e->car_class==4){const int bonus[3][4]={{19,20,22,25},{48,47,23,26},{49,46,24,27}};for(int c=0;c<highest_class;++c)for(int b:bonus[c])if(b==id)return true;return false;}if(e->car_class>highest_class)return false;if(e->stage==1)return true;for(auto&p:r.events)if(p.car_class==e->car_class&&p.course==e->course&&p.stage==e->stage-1)return position(p.level)>=1&&position(p.level)<=3;return false;}
int CareerProgress::settle(const CareerRules&r,int place,double seconds,bool finished,bool dnf){if(!pending)return 0;pending=false;auto e=r.event(pending_level);if(!e||!finished||dnf||place<1||place>8||!std::isfinite(seconds)||seconds<0)return 0;int award=place<=7?e->prizes[place-1]:0;auto old=position(e->level);if(!old||place<old)positions[e->level]=place;auto bt=best_times.find(e->level);if(bt==best_times.end()||seconds<bt->second)best_times[e->level]=seconds;if(e->car_class<=3&&!classes_paid[e->car_class-1]){bool complete=true,has_final=false;for(auto&f:r.events)if(f.car_class==e->car_class&&f.stage==3){has_final=true;int p=position(f.level);if(p<1||p>3)complete=false;}if(complete&&has_final){classes_paid[e->car_class-1]=true;award+=r.completion_prizes[e->car_class-1];highest_class=std::max(highest_class,std::min(3,e->car_class+1));}}return award;}
Json CareerProgress::json()const{Json p=Json::object(),t=Json::object();for(auto&v:positions)p[std::to_string(v.first)]=v.second;for(auto&v:best_times)t[std::to_string(v.first)]=v.second;return {{"initialized",initialized},{"car",car},{"car_price",car_price},{"skin",skin},{"highest_class",highest_class},{"positions",p},{"best_times",t},{"classes_paid",classes_paid},{"attempt",attempt},{"pending",pending},{"pending_level",pending_level}};}
void CareerProgress::load(const Json&j){try{initialized=j.value("initialized",false);car=j.value("car",0);car_price=std::max(0,j.value("car_price",0));skin=j.value("skin",1);highest_class=std::clamp(j.value("highest_class",1),1,3);classes_paid=j.value("classes_paid",classes_paid);attempt=j.value("attempt",uint64_t(0));positions.clear();best_times.clear();for(auto i=j.at("positions").begin();i!=j.at("positions").end();++i){int v=i.value();if(v>=1&&v<=8)positions[std::stoi(i.key())]=v;}if(j.contains("best_times"))for(auto i=j.at("best_times").begin();i!=j.at("best_times").end();++i)best_times[std::stoi(i.key())]=i.value();}catch(const std::exception&){}pending=false;pending_level=0;}
}
